{
  "name": "电化学恒电位仪",
  "name_en": "Potentiostat",
  "manufacturer": "Zahner",
  "description": "这是一种用于电化学实验的恒电位仪，可在测量过程中控制或扫描电位，并采集电流、电压及其随时间变化的数据。它常用于电化学表征、极化测试和其他需要实时观察电流-电压响应的实验。",
  "description_en": "This is a potentiostat for electrochemical experiments. It controls or scans electrode potential during a measurement and acquires current, voltage, and time-dependent signals. It is commonly used for electrochemical characterization, polarization tests, and other experiments that require live monitoring of current-voltage behavior.",
  "tag_hints": [
    "potentiostat",
    "electrochemistry",
    "current-voltage measurement",
    "live measurement display",
    "time-resolved data acquisition"
  ],
  "actions": [
    {
      "action_name": "auto-stopProcessingLoop",
      "description": "停止在线测量数据显示的数据处理循环。",
      "description_en": "Stop the data-processing loop for the live measurement display."
    },
    {
      "action_name": "auto-setMinimumSendInterval",
      "description": "设置向在线显示发送测量数据的最小时间间隔。",
      "description_en": "Set the minimum time interval for sending measurement data to the live display."
    },
    {
      "action_name": "auto-processingLoop",
      "description": "运行在线测量数据显示的数据处理循环。",
      "description_en": "Run the data-processing loop for the live measurement display."
    },
    {
      "action_name": "auto-close",
      "description": "关闭在线测量数据显示窗口。",
      "description_en": "Close the live measurement display window."
    }
  ]
}

